const cfg = $item(0).$node['Config'].json;

const bodies = {
  empreendimentos: String($item(0).$node['Baixar empreendimentos'].json.body ?? ''),
  sitemapIndex: String($item(0).$node['Baixar sitemap index'].json.body ?? ''),
  pageSitemap: String($item(0).$node['Baixar page sitemap'].json.body ?? ''),
  wpApi: String($item(0).$node['Baixar WP API pages'].json.body ?? '')
};

const status = {
  empreendimentos: Number($item(0).$node['Baixar empreendimentos'].json.statusCode ?? 0),
  sitemapIndex: Number($item(0).$node['Baixar sitemap index'].json.statusCode ?? 0),
  pageSitemap: Number($item(0).$node['Baixar page sitemap'].json.statusCode ?? 0),
  wpApi: Number($item(0).$node['Baixar WP API pages'].json.statusCode ?? 0)
};

const normalize = (u) => {
  if (!u || typeof u !== 'string') return null;
  let v = u.trim();
  v = v.replace(/\\u002F/g, '/');
  v = v.replace(/\\\//g, '/');
  v = v.replace(/["'<>]/g, '');
  if (v.startsWith('//')) v = 'https:' + v;
  if (v.startsWith('/')) v = 'https://www.melnick.com.br' + v;
  if (!/^https?:\/\//i.test(v)) return null;
  if (!/\/enterprise\//i.test(v)) return null;
  v = v.replace(/#.*$/, '').replace(/\?.*$/, '').replace(/\/$/, '') + '/';
  return v;
};

const fromBody = (body) => {
  const out = [];
  const regexes = [
    new RegExp('https?:\\\\/\\\\/www\\\\.melnick\\\\.com\\\\.br\\\\/enterprise\\\\/[A-Za-z0-9_-]+(?:\\\\/[A-Za-z0-9_-]+)*', 'gi'),
    new RegExp('\\\\/enterprise\\\\/[A-Za-z0-9_-]+(?:\\\\/[A-Za-z0-9_-]+)*', 'gi'),
    new RegExp('"url"\\\\s*:\\\\s*"([^"\\\\n]*\\\\/enterprise\\\\/[^"\\\\n]*)"', 'gi'),
    new RegExp('href\\\\s*=\\\\s*"([^"\\\\n]*\\\\/enterprise\\\\/[^"\\\\n]*)"', 'gi'),
    new RegExp('<loc>([^<]*\\\\/enterprise\\\\/[^<]*)<\\\\/loc>', 'gi')
  ];

  for (const rgx of regexes) {
    while (true) {
      const m = rgx.exec(body);
      if (!m) break;
      out.push(m[1] || m[0]);
    }
  }
  return out;
};

const all = new Set();
const sourceCounts = {
  empreendimentos: 0,
  sitemapIndex: 0,
  pageSitemap: 0,
  wpApi: 0,
  seed: 0
};

for (const key of Object.keys(bodies)) {
  const arr = fromBody(bodies[key]);
  for (const candidate of arr) {
    const norm = normalize(candidate);
    if (norm && !all.has(norm)) {
      all.add(norm);
      sourceCounts[key] += 1;
    }
  }
}

let seedUrls = [];
try {
  const parsed = JSON.parse(String(cfg.seedUrlsJson || '[]'));
  if (Array.isArray(parsed)) seedUrls = parsed;
} catch (e) {
  seedUrls = [];
}

for (const s of seedUrls) {
  const norm = normalize(s);
  if (norm && !all.has(norm)) {
    all.add(norm);
    sourceCounts.seed += 1;
  }
}

const links = [...all].sort().slice(0, Number(cfg.maxLinks ?? 120));
const bodyLength = {
  empreendimentos: bodies.empreendimentos.length,
  sitemapIndex: bodies.sitemapIndex.length,
  pageSitemap: bodies.pageSitemap.length,
  wpApi: bodies.wpApi.length
};

if (!links.length) {
  return [{
    json: {
      status: 'sem_links',
      totalLinks: 0,
      links: [],
      status,
      bodyLength,
      sourceCounts
    }
  }];
}

return links.map((empreendimentoUrl, i) => ({
  json: {
    indice: i + 1,
    totalLinks: links.length,
    empreendimentoUrl,
    status,
    bodyLength,
    sourceCounts
  }
}));
